if CUR_MARK not in src:
    print('ОШИБКА: не найдена строка версии post-459')
    sys.exit(1)

# индексы текущей строки 3
i3 = src.index(CUR_MARK)
i3end = src.index('\n', i3)
old_line3 = src[i3:i3end]

# (а) удалить СТАРУЮ строку «предыдущая» (post-450; идёт ПОСЛЕ строки 3)
if PREV_MARK in src:
    iprev = src.index(PREV_MARK)
    iprev_end = src.index('\n', iprev)
    src = src[:iprev] + src[iprev_end + 1:]

# (б) строка 3 → новая версия + «предыдущая» из старой строки 3
new_prev = PREV_MARK + ' ' + old_line3[len('> **Версия документа:** '):]
src = src[:i3] + NEW_LINE3 + '\n' + new_prev + src[i3end:]

# (в) обновить ожидание по тестам
old_expect = '# Ожидается: 5023 passed, 0 failed (kip8test; в kip8 — 5029 passed, 0 failed)'
new_expect = '# Ожидается: 5107 passed, 0 failed (kip8test; в kip8 — 5029 passed, 0 failed)'
if old_expect not in src:
    print('ОШИБКА: не найдена строка ожидания тестов')
    sys.exit(1)
src = src.replace(old_expect, new_expect, 1)

# проверки
checks = [
    ('post-Task 462', 1),
    ('Версия документа (предыдущая):** 2026-10-01 (post-Task 459', 1),
    ('5107 passed, 0 failed (kip8test', 1),
    ('kipia-test-v686', None),
    ('post-Task 450', 0),  # старая предыдущая версия удалена
]
for marker, cnt in checks:
    c = src.count(marker)
    if cnt is not None and c != cnt:
        print('ОШИБКА: маркер %r найден %d раз (ожидалось %s)' % (marker[:60], c, cnt))
        sys.exit(1)
    if cnt is None and c == 0:
        print('ОШИБКА: маркер не найден: %r' % marker[:60])
        sys.exit(1)

with io.open(PATH, 'w', encoding='utf-8') as f:
    f.write(src)
print('промт: post-462 записан (+сводки 460/461; ожидание тестов 5107/0)')
